const assert = require("node:assert/strict");
const { execFileSync } = require("node:child_process");

function runTest(cases, expected) {
  const actual = JSON.parse(execFileSync(process.execPath, ["main.cjs", JSON.stringify(cases)], { encoding: "utf8" }));
  assert.deepEqual(actual, expected);
}

// Test 1: Null deletes a key
runTest(
  [{"layers": [{"a": 1, "b": 2}, {"a": null, "c": 3}]}],
  [{"b": 2, "c": 3}]
);

// Test 2: Nested null deletion
runsTest = function() {
  runTest(
    [{"layers": [{"a": {"b": 1, "c": 2}}, {"a": {"b": null}}]}],
    [{"a": {"c": 2}}]
  );
}
runsTest();

// Test 3: Arrays replace earlier values
runTest(
  [{"layers": [{"a": [1, 2]}, {"a": [3]}]}],
  [{"a": [3]}]
);

// Test 4: Falsy values (0, "", false) are preserved
runTest(
  [{"layers": [{"a": 1}, {"a": 0}]}],
  [{"a": 0}]
);
runTest(
  [{"layers": [{"a": 1}, {"a": ""}]}],
  [{"a": ""}]
);
runTest(
  [{"layers": [{"a": 1}, {"a": false}]}],
  [{"a": false}]
);

// Test 5: Deeply nested objects
runTest(
  [{"layers": [{"a": {"b": {"c": 1}}}, {"a": {"b": {"d": 2}}}]}],
  [{"a": {"b": {"c": 1, "d": 2}}}]
);

// Test 6: Deeply nested null
runTest(
  [{"layers": [{"a": {"b": {"c": 1}}}, {"a": {"b": {"c": null}}}]}],
  [{"a": {"b": {}}}]
);

console.log("All regression tests passed");

