import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_empty_events(self):
        x = {'events': [], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {})

    def test_all_in_window(self):
        x = {'events': [{'user': 'a', 'at': 95, 'units': 2}, {'user': 'b', 'at': 90, 'units': 5}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {'a': 2, 'b': 5})

    def test_all_past(self):
        x = {'events': [{'user': 'a', 'at': 80, 'units': 2}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {})

    def test_all_future(self):
        x = {'events': [{'user': 'a', 'at': 110, 'units': 2}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {})

    def test_mixed(self):
        x = {
            'events': [
                {'user': 'a', 'at': 95, 'units': 2},
                {'user': 'b', 'at': 85, 'units': 5},
                {'user': 'c', 'at': 105, 'units': 1},
            ],
            'now': 100,
            'window': 10
        }
        self.assertEqual(solve(x), {'a': 2})

    def test_boundaries(self):
        # Window is [90, 100]
        x = {
            'events': [
                {'user': 'start', 'at': 90, 'units': 1},
                {'user': 'end', 'at': 100, 'units': 2},
                {'user': 'near_start', 'at': 91, 'units': 3},
                {'user': 'near_end', 'at': 99, 'units': 4},
            ],
            'now': 100,
            'window': 10
        }
        self.assertEqual(solve(x), {'start': 1, 'end': 2, 'near_start': 3, 'near_end': 4})

    def test_zero_unit_user(self):
        x = {
            'events': [
                {'user': 'zero', 'at': 95, 'units': 0},
                {'user': 'normal', 'at': 95, 'units': 5},
            ],
            'now': 100,
            'window': 10
        }
        self.assertEqual(solve(x), {'zero': 0, 'normal': 5})

if __name__ == '__main__':
    unittest.main()

