package main
import "sort"
func solve(x map[string]any) any {
	latest := make(map[string]map[string]any)
	orders, ok := x["orders"].([]any)
	if !ok {
		return []string{}
	}
	for _, raw := range orders {
		o, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		id, ok := o["id"].(string)
		if !ok {
			continue
		}
		u, ok := o["updatedAt"].(float64)
		if !ok {
			continue
		}
		if cur, ok := latest[id]; ok {
			cu, _ := cur["updatedAt"].(float64)
			if u >= cu {
				latest[id] = o
			}
		} else {
			latest[id] = o
		}
	}
	out := []string{}
	for id, o := range latest {
		if s, _ := o["status"].(string); s != "cancelled" {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

