exports.solve = function(x) {
  const latestMap = new Map();
  for (const o of x.orders) {
    const existing = latestMap.get(o.id);
    if (!existing || o.updatedAt >= existing.updatedAt) {
      latestMap.set(o.id, o);
    }
  }
  const result = [];
  for (const o of latestMap.values()) {
    if (o.status !== 'cancelled') {
      result.push(o.id);
    }
  }
  return result.sort();
};

