package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestMerge(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name: "README example",
			input: `[
				{
					"layers": [
						{
							"service": {
								"port": 80,
								"tls": true
							},
							"tags": [
								"old"
							]
						},
						{
							"service": {
								"port": 0
							},
							"tags": []
						}
					]
				}
			]`,
			expected: `[
				{
					"service": {
						"port": 0,
						"tls": true
					},
					"tags": []
				}
			]`,
		},
		{
			name: "Null deletes key",
			input: `[
				{
					"layers": [
						{"a": 1},
						{"a": null}
					]
				}
			]`,
			expected: `[
				{}
			]`,
		},
		{
			name: "Null deletes nested key",
			input: `[
				{
					"layers": [
						{"a": {"b": 1}},
						{"a": {"b": null}}
					]
				}
			]`,
			expected: `[
				{"a": {}}
			]`,
		},
		{
			name: "Null deletes nested object",
			input: `[
				{
					"layers": [
						{"a": {"b": 1}},
						{"a": null}
					]
				}
			]`,
			expected: `[
				{}
			]`,
		},
		{
			name: "Empty values remain valid",
			input: `[
				{
					"layers": [
						{"a": 1},
						{"a": 0},
						{"b": true},
						{"b": false},
						{"c": "hello"},
						{"c": ""}
					]
				}
			]`,
			expected: `[
				{"a": 0, "b": false, "c": ""}
			]`,
		},
		{
			name: "Array replaces previous",
			input: `[
				{
					"layers": [
						{"tags": ["a", "b"]},
						{"tags": ["c"]}
					]
				}
			]`,
			expected: `[
				{"tags": ["c"]}
			]`,
		},
		{
			name: "Deep merge",
			input: `[
				{
					"layers": [
						{"x": {"y": {"z": 1}}},
						{"x": {"y": {"w": 2}}}
					]
				}
			]`,
			expected: `[
				{"x": {"y": {"z": 1, "w": 2}}}
			]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var inputs []map[string]any
			if err := json.Unmarshal([]byte(tt.input), &inputs); err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			var results []any
			for _, x := range inputs {
				results = append(results, solve(x))
			}

			actualJSON, err := json.Marshal(results)
			if err != nil {
				t.Fatalf("failed to marshal results: %v", err)
			}

			var actualExpected []any
			if err := json.Unmarshal([]byte(tt.expected), &actualExpected); err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			// To compare easily, we'll unmarshal both to map/slice
			var actualMap any
			_ = json.Unmarshal(actualJSON, &actualMap)
			var expectedMap any
			_ = json.Unmarshal([]byte(tt.expected), &expectedMap)

			if !reflect.DeepEqual(actualMap, expectedMap) {
				t.Errorf("got %s, want %s", string(actualJSON), tt.expected)
			}
		})
	}
}

