package main

func solve(x map[string]any) any {
	var merge func(map[string]any, map[string]any) map[string]any
	merge = func(a, b map[string]any) map[string]any {
		out := make(map[string]any)
		for k, v := range a {
			out[k] = v
		}
		for k, v := range b {
			if v == nil {
				delete(out, k)
			} else if obj, ok := v.(map[string]any); ok {
				old, _ := out[k].(map[string]any)
				out[k] = merge(old, obj)
			} else {
				out[k] = v
			}
		}
		return out
	}

	out := make(map[string]any)
	layers, ok := x["layers"].([]any)
	if !ok {
		return out
	}

	for _, v := range layers {
		if layer, ok := v.(map[string]any); ok {
			out = merge(out, layer)
		}
	}
	return out
}

