package main

func solve(x map[string]any) any {
	var merge func(map[string]any, map[string]any) map[string]any
	merge = func(a, b map[string]any) map[string]any {
		out := make(map[string]any)
		for k, v := range a {
			out[k] = v
		}
		for k, v := range b {
			if v == nil {
				delete(out, k)
			} else if obj, ok := v.(map[string]any); ok {
				if old, ok := out[k].(map[string]any); ok {
					out[k] = merge(old, obj)
				} else {
					out[k] = merge(nil, obj)
				}
			} else {
				out[k] = v
			}
		}
		return out
	}

	out := make(map[string]any)
	layers, ok := x["layers"].([]any)
	if !ok {
		return out
	}

	for _, v := range layers {
		if layer, ok := v.(map[string]any); ok {
			out = merge(out, layer)
		}
	}
	return out
}

package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{
			input:    `[{"layers": []}]`,
			expected: `[{}]`,
		},
		{
			input:    `[{"layers": [{"a": 1}]}]`,
			expected: `[{"a": 1}]`,
		},
		{
			input:    `[{"layers": [{"a": 1}, {"a": null}]}]`,
			expected: `[{}]`,
		},
		{
			input:    `[{"layers": [{"a": {"b": 1}}, {"a": {"c": 2}}]}]`,
			expected: `[{"a": {"b": 1, "c": 2}}]`,
		},
		{
			input:    `[{"layers": [{"a": 1}, {"a": {"b": 2}}]}]`,
			expected: `[{"a": {"b": 2}}]`,
		},
		{
			input:    `[{"layers": [{"a": {"b": 2}}, {"a": 1}]}]`,
			expected: `[{"a": 1}]`,
		},
		{
			input:    `[{"layers": [{"tags": ["old"]}, {"tags": ["new"]}]}]`,
			expected: `[{"tags": ["new"]}]`,
		},
		{
			input:    `[{"layers": [{"service": {"port": 80, "tls": true}, "tags": ["old"]}, {"service": {"port": 0}, "tags": []}]}]`,
			expected: `[{"service": {"port": 0, "tls": true}, "tags": []}]`,
		},
		{
			input:    `[{"layers": [{"a": {"b": {"c": 1}}}, {"a": {"b": {"d": 2}}}]}]`,
			expected: `[{"a": {"b": {"c": 1, "d": 2}}}]`,
		},
	}

	for i, tt := range tests {
		var inputs []map[string]any
		if err := json.Unmarshal([]byte(tt.input), &inputs); err != nil {
			t.Fatalf("case %d: unmarshal input error: %v", i, err)
		}

		var expected []any
		if err := json.Unmarshal([]byte(tt.expected), &expected); err != nil {
			t.Fatalf("case %d: unmarshal expected error: %v", i, err)
		}

		var actual []any
		for _, x := range inputs {
			res := solve(x)
			// To compare properly with json.Unmarshal, we should marshal and unmarshal actual
			b, _ := json.Marshal(res)
			var actualItem any
			json.Unmarshal(b, &actualItem)
			actual = append(actual, actualItem)
		}

		if !reflect.DeepEqual(actual, expected) {
			t.Errorf("case %d: got %v want %v", i, actual, expected)
		}
	}
}

