package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestSolveRegression(t *testing.T) {
	tests := []struct {
		input    map[string]any
		expected []any
	}{
		{
			input: map[string]any{
				"windows": [][2]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: []any{
				[][2]float64{{1, 8}, {9, 10}},
			},
		},
		{
			input: map[string]any{
				"windows": [][2]float64{{5, 5}, {6, 4}, {7, 8}},
			},
			expected: []any{
				[][2]float64{{7, 8}},
			},
		},
		{
			input: map[string]any{
				"windows": [][2]float64{{-10, -5}, {-7, -2}, {-3, 0}},
			},
			expected: []any{
				[][2]float64{{-10, -2}, {-3, 0}},
			},
		},
		{
			input: map[string]any{
				"windows": [][2]float64{{-5, -2}, {-2, 0}, {0, 2}},
			},
			expected: []any{
				[][2]float64{{-5, 2}},
			},
		},
		{
			input: map[string]any{
				"windows": [][2]float64{{1, 2}, {2, 3}, {3, 4}},
			},
			expected: []any{
				[][2]float64{{1, 4}},
			},
		},
	}

	for i, tt := range tests {
		got := solve(tt.input)
		// Convert got to JSON and back to avoid type issues with any
		b, _ := json.Marshal(got)
		var actual any
		_ = json.Unmarshal(b, &actual)

		if !reflect.DeepEqual(actual, tt.expected[0]) { // Wait, tt.expected is []any, so tt.expected[0] is the actual expected value?
			// Looking at the test structure, tt.expected should be the expected result.
		}
	}
}

package main

import (
	"reflect"
	"testing"
)

func TestSolveRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    map[string]any
		expected [][2]float64
	}{
		{
			name: "Example from README",
			input: map[string]any{
				"windows": [][2]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: [][2]float64{{1, 8}, {9, 10}},
		},
		{
			name: "Discard empty and reversed",
			input: map[string]any{
				"windows": [][2]float64{{5, 5}, {6, 4}, {7, 8}},
			},
			expected: [][2]float64{{7, 8}},
		},
		{
			name: "Negative windows",
			input: map[string]any{
				"windows": [][2]float64{{-10, -5}, {-7, -2}, {-3, 0}},
			},
			expected: [][2]float64{{-10, -2}, {-3, 0}},
		},
		{
			name: "Touching and overlapping negative",
			input: map[string]any{
				"windows": [][2]float64{{-5, -2}, {-2, 0}, {0, 2}},
			},
			expected: [][2]float64{{-5, 2}},
		},
		{
			name: "Touching positive",
			input: map[string]any{
				"windows": [][2]float64{{1, 2}, {2, 3}, {3, 4}},
			},
			expected: [][2]float64{{1, 4}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := solve(tt.input).([][2]float64)
			if !reflect.DeepEqual(got, tt.expected) {
				t.Errorf("got %v, want %v", got, tt.expected)
			}
		})
	}
}

