import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_readme_example(self):
        cases = [{
            "layers": [
                {
                    "service": {
                        "port": 80,
                        "tls": True
                    },
                    "tags": ["old"]
                },
                {
                    "service": {
                        "port": 0
                    },
                    "tags": []
                }
            ]
        }]
        expected = [{
            "service": {
                "port": 0,
                "tls": True
            },
            "tags": []
        }]
        self.assertEqual(solve(cases[0]), expected[0])

    def test_null_deletes_key(self):
        cases = [{
            "layers": [
                {"a": 1, "b": 2},
                {"a": None}
            ]
        }]
        expected = [{"b": 2}]
        self.assertEqual(solve(cases[0]), expected[0])

    def test_nested_null_deletes_key(self):
        cases = [{
            "layers": [
                {"a": {"b": 1, "c": 2}},
                {"a": {"b": None}}
            ]
        }]
        expected = [{"a": {"c": 2}}]
        self.assertEqual(solve(cases[0]), expected[0])

    def test_array_replaces_value(self):
        cases = [{
            "layers": [
                {"a": [1, 2]},
                {"a": [3]}
            ]
        }]
        expected = [{"a": [3]}]
        self.assertEqual(solve(cases[0]), expected[0])

    def test_false_zero_empty_string_preserved(self):
        cases = [{
            "layers": [
                {"a": True, "b": 1, "c": "hello"},
                {"a": False, "b": 0, "c": ""}
            ]
        }]
        expected = [{"a": False, "b": 0, "c": ""}]
        self.assertEqual(solve(cases[0]), expected[0])

    def test_empty_layers(self):
        cases = [{"layers": []}]
        expected = {}
        self.assertEqual(solve(cases[0]), expected)

if __name__ == '__main__':
    unittest.main()

