func TestSolveRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "empty orders",
			input:    `[{"orders": []}]`,
			expected: `[[]]`,
		},
		{
			name:     "single order",
			input:    `[{"orders": [{"id": "a", "updatedAt": 1, "status": "open"}]}]`,
			expected: `[["a"]]`,
		},
		{
			name:     "multiple ids sorted lexicographically",
			input:    `[{"orders": [{"id": "z", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 1, "status": "open"}]}]`,
			expected: `[["a", "z"]]`,
		},
		{
			name:     "greatest updatedAt wins",
			input:    `[{"orders": [{"id": "a", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 2, "status": "cancelled"}]}]`,
			expected: `[[]]`,
		},
		{
			name:     "greatest updatedAt wins - status open",
			input:    `[{"orders": [{"id": "a", "updatedAt": 2, "status": "open"}, {"id": "a", "updatedAt": 1, "status": "cancelled"}]}]`,
			expected: `[["a"]]`,
		},
		{
			name:     "tie breaking - later record wins",
			input:    `[{"orders": [{"id": "a", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 1, "status": "cancelled"}]}]`,
			expected: `[[]]`,
		},
		{
			name:     "tie breaking - later record wins - status open",
			input:    `[{"orders": [{"id": "a", "updatedAt": 1, "status": "cancelled"}, {"id": "a", "updatedAt": 1, "status": "open"}]}]`,
			expected: `[["a"]]`,
		},
		{
			name:     "mixed orders with tie",
			input:    `[{"orders": [{"id": "a", "updatedAt": 1, "status": "open"}, {"id": "b", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 1, "status": "cancelled"}]}]`,
			expected: `[["b"]]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var inputs []map[string]any
			if err := json.Unmarshal([]byte(tt.input), &inputs); err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			var expected []any
			if err := json.Unmarshal([]byte(tt.expected), &expected); err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			actualResults := make([]any, len(inputs))
			for i, x := range inputs {
				res := solve(x)
				// Marshal and unmarshal to ensure type consistency for comparison
				b, err := json.Marshal(res)
				if err != nil {
					t.Fatalf("failed to marshal result: %v", err)
				}
				var actual any
				if err := json.Unmarshal(b, &actual); err != nil {
					t.Fatalf("failed to unmarshal actual result: %v", err)
				}
				actualResults[i] = actual
			}

			if !reflect.DeepEqual(actualResults, expected) {
				t.Errorf("got %v, want %v", actualResults, expected)
			}
		})
	}
}

