        # [90, 100]
        x = {'events': [{'user': 'a', 'at': 100, 'units': 2}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {'a': 2})

    def test_outside_left(self):
        # [90, 100]
        x = {'events': [{'user': 'a', 'at': 89, 'units': 5}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {})

    def test_outside_right(self):
        # [90, 100]
        x = {'events': [{'user': 'a', 'at': 101, 'units': 5}], 'now': 100, 'window': 10}
        self.assertEqual(solve(x), {})

    def test_multiple_events(self):
        # [90, 100]
        x = {'events': [
