package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestSolveRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    map[string]any
		expected any
	}{
		{
			name: "Example from README",
			input: map[string]any{
				"windows": [][2]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: [][2]float64{{1, 8}, {9, 10}},
		},
		{
			name: "Empty and reversed windows",
			input: map[string]any{
				"windows": [][2]float64{{5, 5}, {6, 5}, {1, 3}},
			},
			expected: [][2]float64{{1, 3}},
		},
		{
			name: "Touching windows",
			input: map[string]any{
				"windows": [][2]float64{{1, 3}, {3, 5}},
			},
			expected: [][2]float64{{1, 5}},
		},
		{
			name: "Overlapping windows",
			input: map[string]any{
				"windows": [][2]float64{{1, 5}, {2, 4}},
			},
			expected: [][2]float64{{1, 5}},
		},
		{
			name: "Negative endpoints",
			input: map[string]any{
				"windows": [][2]float64{{-10, -5}, {-5, 0}, {-2, 2}},
			},
			expected: [][2]float64{{-10, 2}},
		},
		{
			name: "No windows",
			input: map[string]any{
				"windows": [][2]float64{},
			},
			expected: [][2]float64{},
		},
		{
			name: "Disjoint windows",
			input: map[string]any{
				"windows": [][2]float64{{1, 2}, {4, 5}, {7, 8}},
			},
			expected: [][2]float64{{1, 2}, {4, 5}, {7, 8}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			actual := solve(tt.input)
			// Use JSON marshaling to compare to avoid issues with float64 vs int in any comparison
			// but here we are using [2]float64 directly in expected.
			// Let's convert expected to JSON and unmarshal actual to it for comparison.
			// Or just use reflect.DeepEqual if the types match.

			// In our test, tt.expected is [][2]float64.
			// solve returns any, which is [][2]float64.
			if !reflect.DeepEqual(actual, tt.expected) {
				t.Errorf("got %v, want %v", actual, tt.expected)
			}
		})
	}
}

