package main

import "sort"

func solve(x map[string]any) any {
	rawWindows, ok := x["windows"].([]any)
	if !ok {
		return [][2]float64{}
	}

	var rows [][2]float64
	for _, raw := range rawWindows {
		v, ok := raw.([]any)
		if !ok || len(v) < 2 {
			continue
		}
		a, okA := v[0].(float64)
		b, okB := v[1].(float64)
		if okA && okB && a < b {
			rows = append(rows, [2]float64{a, b})
		}
	}

	sort.Slice(rows, func(i, j int) bool {
		if rows[i][0] != rows[j][0] {
			return rows[i][0] < rows[j][0]
		}
		return rows[i][1] < rows[j][1]
	})

	var out [][2]float64
	for _, v := range rows {
		n := len(out)
		if n > 0 && v[0] <= out[n-1][1] {
			if v[1] > out[n-1][1] {
				out[n-1][1] = v[1]
			}
		} else {
			out = append(out, v)
		}
	}
	return out
}

