package main

import "sort"

func solve(x map[string]any) any {
	orders, ok := x["orders"].([]any)
	if !ok {
		return []string{}
	}

	latest := make(map[string]map[string]any)
	for _, raw := range orders {
		o := raw.(map[string]any)
		id := o["id"].(string)

		u := 0.0
		if v, ok := o["updatedAt"].(float64); ok {
			u = v
		} else if v, ok := o["updatedAt"].(int); ok {
			u = float64(v)
		}

		if existing, ok := latest[id]; ok {
			eU := 0.0
			if v, ok := existing["updatedAt"].(float64); ok {
				eU = v
			} else if v, ok := existing["updatedAt"].(int); ok {
				eU = float64(v)
			}

			if u >= eU {
				latest[id] = o
			}
		} else {
			latest[id] = o
		}
	}

	var out []string
	for id, o := range latest {
		if o["status"] != "cancelled" {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

