package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name: "Example from README",
			input: `{"orders": [
				{"id": "b", "updatedAt": 3, "status": "cancelled"},
				{"id": "b", "updatedAt": 1, "status": "open"},
				{"id": "a", "updatedAt": 2, "status": "open"}
			]}`,
			expected: `["a"]`,
		},
		{
			name: "Tie in updatedAt - later one wins",
			input: `{"orders": [
				{"id": "a", "updatedAt": 1, "status": "open"},
				{"id": "a", "updatedAt": 1, "status": "cancelled"}
			]}`,
			expected: `[]`,
		},
		{
			name: "Tie in updatedAt - earlier one wins (if later is not cancelled)",
			input: `{"orders": [
				{"id": "a", "updatedAt": 1, "status": "cancelled"},
				{"id": "a", "updatedAt": 1, "status": "open"}
			]}`,
			expected: `["a"]`,
		},
		{
			name: "Multiple IDs and sorting",
			input: `{"orders": [
				{"id": "c", "updatedAt": 1, "status": "open"},
				{"id": "b", "updatedAt": 1, "status": "open"},
				{"id": "a", "updatedAt": 1, "status": "open"}
			]}`,
			expected: `["a", "b", "c"]`,
		},
		{
			name: "Empty input",
			input: `{"orders": []}`,
			expected: `[]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var inputMap map[string]any
			if err := json.Unmarshal([]byte(tt.input), &inputMap); err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			result := solve(inputMap)
			resultJSON, _ := json.Marshal(result)

			var expectedSlice []any
			if err := json.Unmarshal([]byte(tt.expected), &expectedSlice); err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			// For comparison, we convert result to map/slice via JSON to be sure about types
			// but here we can just compare JSON strings or use reflect.DeepEqual with unmarshaled expected

			// Since we want to compare the actual result of solve, which is any
			// it's easier to unmarshal the expected JSON into any too.
			var expectedAny any
			_ = json.Unmarshal([]byte(tt.expected), &expectedAny)

			// But wait, unmarshaling [] into any gives []interface{}
			// and our solve returns []string. 
			// json.Marshal(solve) will give the same JSON string as tt.expected.

			if string(resultJSON) != tt.expected {
				// We need to be careful with whitespace but tt.expected is minimal
				// Let's try to normalize or just compare after unmarshaling both
				var actualAny any
				_ = json.Unmarshal(resultJSON, &actualAny)

				if !reflect.DeepEqual(actualAny, expectedAny) {
					t.Errorf("got %s want %s", string(resultJSON), tt.expected)
				}
			}
		})
	}
}

