    def test_reversed_and_empty(self):
        self.assertEqual(solve({'windows': [[5, 1], [5, 5]]}), [])

    def test_negative_endpoints(self):
        self.assertEqual(solve({'windows': [[-5, -2], [-3, 0]]}), [[-5, 0]])

    def test_negative_touching(self):
        self.assertEqual(solve({'windows': [[-5, -2], [-2, 0]]}), [[-5, 0]])

    def test_mixed(self):
        self.assertEqual(solve({'windows': [[1, 5], [10, 12], [3, 7]]}), [[1, 7], [10, 12]])

