import unittest
from logic import solve

class TestRegression(unittest.TestCase):
    def test_basic_merge(self):
        layers = [
            {'a': 1, 'b': 2},
            {'b': 3, 'c': 4}
        ]
        x = {'layers': layers}
        # merge({}, {'a': 1, 'b': 2}) -> {'a': 1, 'b': 2}
        # merge({'a': 1, 'b': 2}, {'b': 3, 'c': 4}) -> {'a': 1, 'b': 3, 'c': 4}
        expected = {'a': 1, 'b': 3, 'c': 4}
        self.assertEqual(solve(x), expected)

    def test_recursive_merge(self):
        layers = [
            {'a': {'b': 1, 'c': 2}},
            {'a': {'c': 3, 'd': 4}}
        ]
        x = {'layers': layers}
        # merge({}, {'a': {'b': 1, 'c': 2}}) -> {'a': {'b': 1, 'c': 2}}
        # merge({'a': {'b': 1, 'c': 2}}, {'a': {'c': 3, 'd': 4}})
        #   merge({'b': 1, 'c': 2}, {'c': 3, 'd': 4}) -> {'b': 1, 'c': 3, 'd': 4}
        #   -> {'a': {'b': 1, 'c': 3, 'd': 4}}
        expected = {'a': {'b': 1, 'c': 3, 'd': 4}}
        self.assertEqual(solve(x), expected)

    def test_null_deletes_key(self):
        layers = [
            {'a': 1, 'b': 2},
            {'b': None, 'c': 3}
        ]
        x = {'layers': layers}
        # merge({'a': 1, 'b': 2}, {'b': None, 'c': 3}) -> {'a': 1, 'c': 3}
        expected = {'a': 1, 'c': 3}
        self.assertEqual(solve(x), expected)

    def test_replace_values(self):
        layers = [
            {'a': [1, 2], 'b': 10},
            {'a': [3], 'b': 20}
        ]
        x = {'layers': layers}
        # merge({'a': [1, 2], 'b': 10}, {'a': [3], 'b': 20}) -> {'a': [3], 'b': 20}
        expected = {'a': [3], 'b': 20}
        self.assertEqual(solve(x), expected)

    def test_valid_values(self):
        layers = [
            {'a': 1, 'b': 2, 'c': 3},
            {'a': 0, 'b': False, 'c': ""}
        ]
        x = {'layers': layers}
        # merge({'a': 1, 'b': 2, 'c': 3}, {'a': 0, 'b': False, 'c': ""}) -> {'a': 0, 'b': False, 'c': ""}
        expected = {'a': 0, 'b': False, 'c': ""}
        self.assertEqual(solve(x), expected)

    def test_no_mutation(self):
        layer1 = {'a': {'b': 1}}
        layer2 = {'a': {'c': 2}}
        layers = [layer1, layer2]
        x = {'layers': layers}
        solve(x)
        self.assertEqual(layer1, {'a': {'b': 1}})
        self.assertEqual(layer2, {'a': {'c': 2}})

    def test_readme_example(self):
