import unittest
import json, subprocess, sys
from logic import solve

class TestLayeredConfig(unittest.TestCase):
    def test_readme_example(self):
        input_data = {
            "layers": [
                {
                    "service": {
                        "port": 80,
                        "tls": True
                    },
                    "tags": ["old"]
                },
                {
                    "service": {
                        "port": 0
                    },
                    "tags": []
                }
            ]
        }
        expected = {
            "service": {
                "port": 0,
                "tls": True
            },
            "tags": []
        }
        self.assertEqual(solve(input_data), expected)

    def test_null_deletes_key(self):
        # Top level delete
        input_data = {
            "layers": [
                {"a": 1, "b": 2},
                {"a": None}
            ]
        }
        expected = {"b": 2}
        self.assertEqual(solve(input_data), expected)

        # Nested delete
        input_data = {
            "layers": [
                {"a": {"b": 1, "c": 2}},
                {"a": {"b": None}}
            ]
        }
        expected = {"a": {"c": 2}}
        self.assertEqual(solve(input_data), expected)

    def test_valid_values(self):
        # false, zero and empty strings remain valid
        input_data = {
            "layers": [
                {"a": True, "b": 1, "c": "hello"},
                {"a": False, "b": 0, "c": ""}
            ]
        }
        expected = {"a": False, "b": 0, "c": ""}
