package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{
			input:    `{"orders": [{"id": "b", "updatedAt": 3, "status": "cancelled"}, {"id": "b", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 2, "status": "open"}]}`,
			expected: `["a"]`,
		},
		{
			input:    `{"orders": [{"id": "b", "updatedAt": 1, "status": "open"}, {"id": "b", "updatedAt": 3, "status": "cancelled"}, {"id": "a", "updatedAt": 2, "status": "open"}]}`,
			expected: `["a"]`,
		},
		{
			input:    `{"orders": [{"id": "b", "updatedAt": 3, "status": "open"}, {"id": "b", "updatedAt": 3, "status": "cancelled"}, {"id": "a", "updatedAt": 2, "status": "open"}]}`,
			expected: `["a"]`,
		},
		{
			input:    `{"orders": [{"id": "c", "updatedAt": 1, "status": "open"}, {"id": "b", "updatedAt": 1, "status": "open"}, {"id": "a", "updatedAt": 1, "status": "open"}]}`,
			expected: `["a", "b", "c"]`,
		},
		{
			input:    `{"orders": [{"id": "a", "updatedAt": 1, "status": "cancelled"}, {"id": "b", "updatedAt": 1, "status": "cancelled"}]}`,
			expected: `[]`,
		},
	}

	for _, tc := range tests {
		var inputMap map[string]any
		_ = json.Unmarshal([]byte(tc.input), &inputMap)
		res := solve(inputMap)

		// Marshal the result to compare with expected JSON string
		b, _ := json.Marshal(res)
		actual := string(b)

		// The expected string might be [] or [] instead of [] (wait, [] is [] in JSON)
		// But let's normalize it by unmarshaling expected too.
		var expectedAny any
		_ = json.Unmarshal([]byte(tc.expected), &expectedAny)

		// Need to unmarshal actual as well to ensure type consistency for reflect.DeepEqual
		var actualAny any
		_ = json.Unmarshal(b, &actualAny)

		if !reflect.DeepEqual(actualAny, expectedAny) {
			t.Errorf("input %s: got %v want %v", tc.input, actualAny, expectedAny)
		}
	}
}

