package main

import "sort"

func solve(x map[string]any) any {
	latest := make(map[string]map[string]any)
	orders, _ := x["orders"].([]any)
	getUpd := func(m map[string]any) float64 {
		switch v := m["updatedAt"].(type) {
		case float64:
			return v
		case int:
			return float64(v)
		default:
			return 0
		}
	}
	for _, raw := range orders {
		o, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		id, _ := o["id"].(string)
		if ex, ok := latest[id]; ok {
			if getUpd(o) >= getUpd(ex) {
				latest[id] = o
			}
		} else {
			latest[id] = o
		}
	}
	var out []string
	for id, o := range latest {
		s, _ := o["status"].(string)
		if s != "cancelled" {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

