package main

import "sort"

func solve(x map[string]any) any {
	rows := [][2]float64{}
	for _, raw := range x["windows"].([]any) {
		v := raw.([]any)
		a, b := v[0].(float64), v[1].(float64)
		if a < b {
			rows = append(rows, [2]float64{a, b})
		}
	}
	sort.Slice(rows, func(i, j int) bool {
		return rows[i][0] < rows[j][0] || (rows[i][0] == rows[j][0] && rows[i][1] < rows[j][1])
	})
	out := [][2]float64{}
	for _, v := range rows {
		n := len(out)
		if n > 0 && v[0] <= out[n-1][1] {
			if v[1] > out[n-1][1] {
				out[n-1][1] = v[1]
			}
		} else {
			out = append(out, v)
		}
	}
	return out
}

