// Public tests
const public_cases=[{"windows": []}, {"windows": [[2, 4]]}];
const public_expected=[[], [[2, 4]]];
assert.deepEqual(run(public_cases), public_expected, "Public cases failed");

// Regression tests
const regression_cases = [
  {
    // README example
    input: {"windows": [[5, 8], [1, 3], [3, 5], [9, 10]]},
    expected: [[1, 8], [9, 10]]
  },
  {
    // Empty/reversed windows
    input: {"windows": [[5, 5], [6, 5], [1, 3]]},
    expected: [[1, 3]]
  },
  {
    // Touching and overlapping
    input: {"windows": [[1, 5], [5, 7], [6, 8]]},
    expected: [[1, 8]]
  },
  {
    // Negative windows
    input: {"windows": [[-10, -5], [-7, -3], [-4, -1]]},
    expected: [[-10, -3], [-4, -1]]
  },
  {
    // Negative and zero
    input: {"windows": [[-2, 0], [0, 2]]},
    expected: [[-2, 2]]
  },
  {
    // Single window
    input: {"windows": [[1, 2]]},
    expected: [[1, 2]]
  },
  {
    // No windows
    input: {"windows": []},
    expected: []
  }
];

for (const {input, expected} of regression_cases) {
