import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_empty_orders(self):
        self.assertEqual(solve({"orders": []}), [])

    def test_single_order_open(self):
        self.assertEqual(solve({"orders": [{"id": "a", "updatedAt": 1, "status": "open"}]}), ["a"])

    def test_single_order_cancelled(self):
        self.assertEqual(solve({"orders": [{"id": "a", "updatedAt": 1, "status": "cancelled"}]}), [])

    def test_multiple_orders_sorted(self):
        self.assertEqual(solve({"orders": [
            {"id": "b", "updatedAt": 1, "status": "open"},
            {"id": "a", "updatedAt": 1, "status": "open"}
        ]}), ["a", "b"])

    def test_tie_later_record_wins(self):
        # Tie in updatedAt, second one is cancelled
        self.assertEqual(solve({"orders": [
            {"id": "b", "updatedAt": 1, "status": "open"},
            {"id": "b", "updatedAt": 1, "status": "cancelled"}
        ]}), [])
        # Tie in updatedAt, second one is open
        self.assertEqual(solve({"orders": [
            {"id": "b", "updatedAt": 1, "status": "cancelled"},
            {"id": "b", "updatedAt": 1, "status": "open"}
        ]}), ["b"])

    def test_updated_at_priority(self):
        # Higher updatedAt wins
        self.assertEqual(solve({"orders": [
            {"id": "b", "updatedAt": 1, "status": "open"},
            {"id": "b", "updatedAt": 2, "status": "cancelled"}
        ]}), [])
        self.assertEqual(solve({"orders": [
            {"id": "b", "updatedAt": 2, "status": "cancelled"},
            {"id": "b", "updatedAt": 1, "status": "open"}
        ]}), ["b"])

    def test_readme_example(self):
        self.assertEqual(solve({
            "orders": [
                {"id": "b", "updatedAt": 3, "status": "cancelled"},
                {"id": "b", "updatedAt": 1, "status": "open"},
                {"id": "a", "updatedAt": 2, "status": "open"}
            ]
        }), ["a"])

if __name__ == "__main__":
    unittest.main()

