package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		input    string
		expected string
	}{
		{
			input:    `[{"events": [], "now": 100, "window": 10}]`,
			expected: `[{}]`,
		},
		{
			input:    `[{"events": [{"user": "a", "at": 100, "units": 5}], "now": 100, "window": 0}]`,
			expected: `[{"a": 5}]`,
		},
		{
			input:    `[{"events": [{"user": "a", "at": 100, "units": 5}], "now": 100, "window": 10}]`,
			expected: `[{"a": 5}]`,
		},
