import unittest
from logic import solve

class TestRegression(unittest.TestCase):
    def test_window_boundaries(self):
        # Boundary: at = now - window
        case1 = {
            "events": [{"user": "a", "at": 90, "units": 5}],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case1), {"a": 5})

        # Boundary: at = now
        case2 = {
            "            "events": [{"user": "a", "at": 100, "units": 5}],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case2), {"a": 5})

        # Boundary: at = now - window - 1
        case3 = {
            "events": [{"user": "a", "at": 89, "units": 5}],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case3), {})

        # Boundary: at = now + 1
        case4 = {
            "events": [{"user": "a", "at": 101, "units": 5}],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case4), {})

    def test_empty_events(self):
        case = {
            "events": [],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case), {})

    def test_zero_units(self):
        case = {
            "events": [{"user": "a", "at": 95, "units": 0}],
            "now": 100,
            "window": 10
        }
        self.assertEqual(solve(case), {"a": 0})

    def test_window_zero(self):
        # If window is 0, only events at 'now' should be included.
        case = {
            "events": [
                {"user": "a", "at": 100, "units": 5},
                {"user": "b", "at": 99, "units": 3}
            ],
            "now": 100,
            "window": 0
        }
        self.assertEqual(solve(case), {"a": 5})

    def test_window_large(self):
        case = {
            "events": [
                {"user": "a", "at": 0, "units": 1},
                {"user": "b", "at": 100, "units": 1}
            ],
            "now": 100,
            "window": 100
        }
        self.assertEqual(solve(case), {"a": 1, "b": 1})

if __name__ == '__main__':
    unittest.main()

