package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	inputs := []map[string]any{
		{
			"events": []any{
				map[string]any{"user": "a", "at": 90.0, "units": 3.0},
				map[string]any{"user": "a", "at": 100.0, "units": 2.0},
				map[string]any{"user": "b", "at": 101.0, "units": 9.0},
			},
			"now":    100.0,
			"window": 10.0,
		},
		{
			"events": []any{
				map[string]any{"user": "a", "at": 80.0, "units": 5.0},
				map[string]any{"user": "a", "at": 90.0, "units": 0.0},
				map[string]any{"user": "b", "at": 95.0, "units": 10.0},
			},
			"now":    100.0,
			"window": 20.0,
		},
		{
			"events": []any{
				map[string]any{"user": "a", "at": 100.0, "units": 5.0},
				map[string]any{"user": "b", "at": 100.0, "units": 10.0},
			},
			"now":    100.0,
			"window": 0.0,
		},
	}

	expected := []any{
		map[string]int{"a": 5},
		map[string]int{"a": 5, "b": 10},
		map[string]int{"a": 5, "b": 10},
	}

	for i, x := range inputs {
		res := solve(x)
		b, _ := json.Marshal(res)
		var actual any
		_ = json.Unmarshal(b, &actual)

		// In the test, expected is map[string]int.
		// But json.Unmarshal into 'actual' will make it map[string]interface{} with float64 values.
		// To compare easily, we can convert expected to what json.Unmarshal would produce.

		// Let's use a better way to compare.
		// We'll marshal expected as well.
		eb, _ := json.Marshal(expected[i])
		var expAfterUnmarshal any
		_ = json.Unmarshal(eb, &expAfterUnmarshal)

		if !reflect.DeepEqual(actual, expAfterUnmarshal) {
			t.Fatalf("case %d: got %v want %v", i, actual, expected[i])
		}
	}
}

