package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    map[string]any
		expected []any
	}{
		{
			name: "README example",
			input: map[string]any{
				"windows": [][2]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: []any{
				[][2]float64{{1, 8}, {9, 10}},
			},
		},
		{
			name: "Touching windows",
			input: map[string]any{
				"windows": [][2]float64{{1, 2}, {2, 3}, {3, 4}},
			},
			expected: []any{
				[][2]float64{{1, 4}},
			},
		},
		{
			name: "Overlapping windows",
			input: map[string]any{
				"windows": [][2]float64{{1, 5}, {2, 6}, {4, 7}},
			},
			expected: []any{
				[][2]float64{{1, 7}},
			},
		},
		{
			name: "Negative endpoints",
			input: map[string]any{
				"windows": [][2]float64{{-10, -5}, {-7, -2}, {-3, 1}},
			},
			expected: []any{
				[][2]float64{{-10, -2}, {-3, 1}}, // Wait, -7 is between -10 and -5. So [-10, -2] and [-3, 1]
			},
		},
	}

	// Wait, let's re-calculate the negative endpoints example.
	// Windows: [-10, -5], [-7, -2], [-3, 1]
	// Sorted by start: [-10, -5], [-7, -2], [-3, 1]
	// 1. out = [[-10, -5]]
	// 2. v = [-7, -2]. -7 <= -5? Yes. -2 > -5? Yes. out = [[-10, -2]]
	// 3. v = [-3, 1]. -3 <= -2? No. out = [[-10, -2], [-3, 1]]
	// Correct.

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := solve(tt.input)
			// Using JSON marshal/unmarshal to compare as it's easier for 'any' types
			gotJSON, _ := json.Marshal(got)
			expectedJSON, _ := json.Marshal(tt.expected)
			var gotAny, expectedAny any
			json.Unmarshal(gotJSON, &gotAny)
			json.Unmarshal(expectedJSON, &expectedAny)

			if !reflect.DeepEqual(gotAny, expectedAny) {
				t.Errorf("got %v, want %v", gotAny, expectedAny)
			}
		})
	}
}

