func merge(a, b map[string]any) map[string]any {
	out := make(map[string]any)
	for k, v := range a {
		out[k] = v
	}
	for k, v := range b {
		if v == nil {
			delete(out, k)
		} else if obj, ok := v.(map[string]any); ok {
			if old, ok := out[k].(map[string]any); ok {
				out[k] = merge(old, obj)
			} else {
				out[k] = merge(make(map[string]any), obj)
			}
		} else {
			out[k] = v
		}
	}
	return out
}

func solve(x map[string]any) any {
	layers, ok := x["layers"].([]any)
	if !ok {
		return nil
	}
	out := make(map[string]any)
	for _, layer := range layers {
		l, ok := layer.(map[string]any)
		if !ok {
			continue
		}
		out = merge(out, l)
	}
	return out
}

