package main

import "sort"

func solve(x map[string]any) any {
	type info struct {
		data map[string]any
		u    float64
	}
	latest := make(map[string]info)
	orders, ok := x["orders"].([]any)
	if !ok {
		return []string{}
	}
	for _, raw := range orders {
		o, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		id, ok := o["id"].(string)
		if !ok {
			continue
		}
		u, ok := o["updatedAt"].(float64)
		if !ok {
			continue
		}
		if prev, exists := latest[id]; !exists || u >= prev.u {
			latest[id] = info{data: o, u: u}
		}
	}
	var out []string
	for id, item := range latest {
		status, _ := item.data["status"].(string)
		if status != "cancelled" {
			out = append(out, id)
		}
	}
	sort.Strings(out)
	return out
}

