			name: "Tie in updatedAt takes later record (open)",
			input: `[{"orders": [
				{"id": "a", "updatedAt": 1, "status": "cancelled"},
				{"id": "a", "updatedAt": 1, "status": "open"}
			]}]`,
			expected: `[["a"]]`,
		},
		{
			name: "Multiple orders, some cancelled",
			input: `[{"orders": [
				{"id": "a", "updatedAt": 1, "status": "open"},
				{"id": "b", "updatedAt": 2, "status": "open"},
				{"id": "a", "updatedAt": 3, "status": "cancelled"}
			]}]`,
			expected: `[["b"]]`,
		},
		{
			name: "Empty orders",
			input: `[{"orders": []}]`,
			expected: `[[]]`,
		},
		{
			name: "Empty input",
			input: `[]`,
			expected: `[]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// We need to run the command to match the behavior of main.go
			// But we can just call solve directly for testing logic
			var inputs []map[string]any
			if err := json.Unmarshal([]byte(tt.input), &inputs); err != nil {
				t.Fatal(err)
			}

			var actualOut []any
			for _, x := range inputs {
				res := solve(x)
				// Since solve returns any, which is []string, we need to wrap it in []any for JSON comparison
				// or just use reflect.DeepEqual on the result of solve.
				// The original TestPublic does this:
				// b, _ := json.Marshal(solve(x))
				// var actual any; _ = json.Unmarshal(b, &actual)
				// Let's follow that.
				b, _ := json.Marshal(res)
				var actual any
				_ = json.Unmarshal(b, &actual)
				actualOut = append(actualOut, actual)
			}

			var expected []any
			if err := json.Unmarshal([]byte(tt.expected), &expected); err != nil {
				t.Fatal(err)
			}

			if !reflect.DeepEqual(actualOut, expected) {
				t.Errorf("got %v want %v", actualOut, expected)
			}
		})
	}
}

