package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name: "README example",
			input: `[{"layers": [
    {
      "service": {
        "port": 80,
        "tls": true
      },
      "tags": [
        "old"
      ]
    },
    {
      "service": {
        "port": 0
      },
      "tags": []
    }
  ]}]`,
			expected: `[{"service": {"port": 0, "tls": true}, "tags": []}]`,
		},
		{
			name: "Null deletes key",
			input: `[{"layers": [
    {"a": 1, "b": 2},
    {"a": null}
  ]}]`,
			expected: `[{"b": 2}]`,
		},
		{
			name: "Nested null deletes key",
			input: `[{"layers": [
    {"a": {"b": 1, "c": 2}},
    {"a": {"b": null}}
  ]}]`,
			expected: `[{"a": {"c": 2}}]`,
		},
		{
			name: "Array replaces earlier value",
			input: `[{"layers": [
    {"a": [1, 2]},
    {"a": [3]}
  ]}]`,
			expected: `[{"a": [3]}]`,
		},
		{
			name: "False and zero are valid",
			input: `[{"layers": [
    {"a": true},
    {"a": false}
  ], "layers2": [
    {"b": 1},
    {"b": 0}
  ]}]`,
			// Wait, the input is a JSON array of maps.
			// The example says: {"layers": [...]} is one map.
			// My test input above is slightly wrong in structure.
			// Let's fix it.
			input: `[{"layers": [
    {"a": true},
    {"a": false}
  ]}]`,
			expected: `[{"a": false}]`,
		},
		{
			name: "Zero is valid",
			input: `[{"layers": [
    {"a": 1},
    {"a": 0}
  ]}]`,
			expected: `[{"a": 0}]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var inputs []map[string]any
			err := json.Unmarshal([]byte(tt.input), &inputs)
			if err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			var expected []any
			err = json.Unmarshal([]byte(tt.expected), &expected)
			if err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			for i, x := range inputs {
				res := solve(x)
				b, err := json.Marshal(res)
				if err != nil {
					t.Fatalf("failed to marshal result: %v", err)
				}

				var actual any
				err = json.Unmarshal(b, &actual)
				if err != nil {
					t.Fatalf("failed to unmarshal actual: %v", err)
				}

				if !reflect.DeepEqual(actual, expected[i]) {
					t.Errorf("case %d: got %v want %v", i, actual, expected[i])
				}
			}
		})
	}
}

