import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_empty_layers(self):
        self.assertEqual(solve({"layers": []}), {})

    def test_single_layer(self):
        self.assertEqual(solve({"layers": [{"a": 1}]}), {"a": 1})

    def test_multiple_layers(self):
        self.assertEqual(solve({"layers": [{"a": 1}, {"b": 2}]}), {"a": 1, "b": 2})

    def test_merge_objects(self):
        self.assertEqual(solve({"layers": [{"a": {"x": 1}}, {"a": {"y": 2}}],}), {"a": {"x": 1, "y": 2}})

    def test_null_deletes_key(self):
        self.assertEqual(solve({"layers": [{"a": 1, "b": 2}, {"b": None}]}), {"a": 1})

    def test_replace_with_dict(self):
        self.assertEqual(solve({"layers": [{"a": 1}, {"a": {"x": 2}}],}), {"a": {"x": 2}})

    def test_replace_with_non_dict(self):
        self.assertEqual(solve({"layers": [{"a": {"x": 1}}, {"a": 2}]],}), {"a": 2})

    def test_empty_string_and_zero_are_valid(self):
        self.assertEqual(solve({"layers": [{"a": ""}, {"a": 0}]}), {"a": 0})
        self.assertEqual(solve({"layers": [{"a": 0}, {"a": ""}]}), {"a": ""})
        self.assertEqual(solve({"layers": [{"a": False}, {"a": True}]}), {"a": True})

    def test_example_case(self):
        self.assertEqual(solve({"layers": [{"service": {"port": 80, "tls": True}, "tags": ["old"]}, {"service": {"port": 0}, "tags": []}]}), {"service": {"port": 0, "tls": True}, "tags": []})

if __name__ == '__main__':
    unittest.main()

