package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestREADMEExample(t *testing.T) {
	inputStr := `[{"layers": [{"service": {"port": 80, "tls": true}, "tags": ["old"]}, {"service": {"port": 0}, "tags": []}]}]`
	var inputs []map[string]any
	_ = json.Unmarshal([]byte(inputStr), &inputs)

	expectedStr := `[{"service": {"port": 0, "tls": true}, "tags": []}]`
	var expected []any
	_ = json.Unmarshal([]byte(expectedStr), &expected)

	for i, x := range inputs {
		res := solve(x)
		// Marshal and unmarshal to compare JSON structure easily
		b, _ := json.Marshal(res)
		var actual any
		_ = json.Unmarshal(b, &actual)

		// Need to re-marshal expected to compare properly due to types
		bExp, _ := json.Marshal(expected[i])
		var actualExp any
		_ = json.Unmarshal(bExp, &actualExp)

		if !reflect.DeepEqual(actual, actualExp) {
			t.Fatalf("case %d: got %v want %v", i, actual, actualExp)
		}
	}
}

func TestNullDeletion(t *testing.T) {
	inputStr := `[{"layers": [{"a": {"b": 1, "c": 2}}, {"a": {"b": null}}]}]`
	var inputs []map[string]any
	_ = json.Unmarshal([]byte(inputStr), &inputs)

	expectedStr := `[{"a": {"c": 2}}]`
	var expected []any
	_ = json.Unmarshal([]byte(expectedStr), &expected)

	for i, x := range inputs {
		res := solve(x)
		b, _ := json.Marshal(res)
		var actual any
		_ = json.Unmarshal(b, &actual)

		bExp, _ := json.Marshal(expected[i])
		var actualExp any
				_ = json.Unmarshal(bExp, &actualExp)

		if !reflect.DeepEqual(actual, actualExp) {
			t.Fatalf("case %d: got %v want %v", i, actual, actualExp)
		}
	}
}

