package main

func solve(x map[string]any) any {
	layers, ok := x["layers"].([]any)
	if !ok {
		return nil
	}
	out := make(map[string]any)
	for _, layer := range layers {
		l, ok := layer.(map[string]any)
		if !ok {
			continue
		}
		out = merge(out, l)
	}
	return out
}

func merge(a, b map[string]any) map[string]any {
	res := make(map[string]any)
	for k, v := range a {
		res[k] = v
	}
	for k, v := range b {
		if v == nil {
			delete(res, k)
		} else if obj, ok := v.(map[string]any); ok {
			if sub, ok := res[k].(map[string]any); ok {
				res[k] = merge(sub, obj)
			} else {
				res[k] = merge(make(map[string]any), obj)
			}
		} else {
			res[k] = v
		}
	}
	return res
}

