from logic import solve

class TestLogic(unittest.TestCase):
    def test_order_update_stream(self):
        # Test case from README
        input_data = {
            "orders": [
                {
                    "id": "b",
                    "updatedAt": 3,
                    "status": "cancelled"
                },
                {
                    "id": "b",
                    "updatedAt": 1,
                    "status": "open"
                },
                {
                    "id": "a",
                    "updatedAt": 2,
                    "status": "open"
                }
            ]
        }
        expected = ["a"]
        self.assertEqual(solve(input_data), expected)

        # Test case where later record should update
        input_data2 = {
            "orders": [
                {
                    "id": "b",
