                    "updatedAt": 3,
                    "status": "cancelled"
                }
            ]
        }
        expected2 = []
        self.assertEqual(solve(input_data2), expected2)

        # Test case where tie in updatedAt should choose later record
        input_data3 = {
            "orders": [
