import unittest, json, subprocess, sys

class TestRegression(unittest.TestCase):
    def run_main(self, cases):
        p = subprocess.run([sys.executable, "main.py", json.dumps(cases)], capture_output=True, text=True, check=True)
        return json.loads(p.stdout)

    def test_boundaries(self):
        # Window is [90, 100]
        cases = [
