import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_empty_layers(self):
        self.assertEqual(solve({'layers': []}), {})

    def test_single_layer(self):
        self.assertEqual(solve({'layers': [{'a': 1}]}), {'a': 1})

    def test_merge_dict_layers(self):
        layers = [
            {'service': {'port': 80, 'tls': True}, 'tags': ['old']},
            {'service': {'port': 0}, 'tags': []}
        ]
        expected = {'service': {'port': 0, 'tls': True}, 'tags': []}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_null_deletes_key(self):
        layers = [
            {'a': 1, 'b': 2},
            {'b': None, 'c': 3}
        ]
        expected = {'a': 1, 'c': 3}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_array_replacement(self):
        layers = [
            {'tags': ['a', 'b']},
            {'tags': ['c']}
        ]
        expected = {'tags': ['c']}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_false_zero_empty_string_valid(self):
        layers = [
            {'a': True, 'b': 1, 'c': "hello"},
            {'a': False, 'b': 0, 'c': ""}
        ]
        expected = {'a': False, 'b': 0, 'c': ""}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_deep_merge(self):
        layers = [
            {'service': {'config': {'timeout': 30, 'retries': 3}}},
            {'service': {'config': {'timeout': 60}}}
        ]
        expected = {'service': {'config': {'timeout': 60, 'retries': 3}}}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_deep_merge_with_replacement(self):
        # If current value is not a dict, and new value is a dict, it should replace
        layers = [
            {'service': 80},
            {'service': {'port': 80}}
        ]
        expected = {'service': {'port': 80}}
        self.assertEqual(solve({'layers': layers}), expected)

    def test_mutation_check(self):
        # Ensure we don't mutate the input
        layer1 = {'a': {'b': 1}}
        layer2 = {'a': {'c': 2}}
        layers = [{'a': {'b': 1}}, {'a': {'c': 2}}]
        result = solve({'layers': layers})
        self.assertEqual(result, {'a': {'b': 1, 'c': 2}})
        # Check if layer1 was mutated
        self.assertEqual(layer1, {'a': {'b': 1}})

if __name__ == '__main__':
    unittest.main()

