import json, sys, unittest

from logic import solve

class TestMaintenanceWindows(unittest.TestCase):
    def test_readme_example(self):
        input_data = {
            "windows": [
                [5, 8],
                [1, 3],
                [3, 5],
                [9, 10]
            ]
        }
        expected = [[1, 8], [9, 10]]
        self.assertEqual(solve(input_data), expected)

    def test_empty_windows(self):
        input_data = {"windows": [[1, 1], [2, 2], [3, 3]]}
        expected = []
        self.assertEqual(solve(input_data), expected)

    def test_reversed_windows(self):
        input_data = {"windows": [[5, 1], [3, 2]]}
        expected = []
        self.assertEqual(solve(input_data), expected)

    def test_negative_endpoints(self):
        input_data = {"windows": [[-10, -5], [-7, -2], [-3, 0]]}
        # Sorted: [-10, -5], [-7, -2], [-3, 0]
        # [-10, -5] and [-7, -2] overlap/touch? -7 <= -5 is True.
        # Merge [-10, -5] and [-7, -2] -> [-10, -2]
        # [-10, -2] and [-3, 0] overlap/touch? -3 <= -2 is True.
        # Merge [-10, -2] and [-3, 0] -> [-10, 0]
        expected = [[-10, 0]]
        self.assertEqual(solve(input_data), expected)

    def test_no_overlap_negative(self):
        input_data = {"windows": [[-10, -5], [-3, -2]]}
        # Sorted: [-10, -5], [-3, -2]
        # -3 <= -5 is False.
        expected = [[-10, -5], [-3, -2]]
        self.assertEqual(solve(input_data), expected)

    def test_touching_windows_negative(self):
        input_data = {"windows": [[-10, -5], [-5, 0]]}
        # Sorted: [-10, -5], [-5, 0]
        # -5 <= -5 is True.
        # Merge: [-10, 0]
        expected = [[-10, 0]]
        self.assertEqual(solve(input_data), expected)

    def test_non_mutation(self):
        input_data = {"windows": [[1, 5], [3, 7]]}
        input_copy = {"windows": [[1, 5], [3, 7]]}
        solve(input_data)
        self.assertEqual(input_data, input_copy)

if __name__ == "__main__":
    unittest.main()

