func TestSolve_Regression(t *testing.T) {
	type Order struct {
		ID        string `json:"id"`
		UpdatedAt int    `json:"updatedAt"`
		Status    string `json:"status"`
	}

	type Input struct {
		Orders []Order `json:"orders"`
	}

	tests := []struct {
		input    Input
		expected []string
	}{
		{
			input: Input{
				Orders: []Order{
					{ID: "b", UpdatedAt: 1, Status: "open"},
					{ID: "b", UpdatedAt: 3, Status: "cancelled"},
					{ID: "a", UpdatedAt: 2, Status: "open"},
				},
			},
			expected: []string{"a"},
		},
		{
			input: Input{
				Orders: []Order{
					{ID: "a", UpdatedAt: 1, Status: "open"},
					{ID: "a", UpdatedAt: 1, Status: "cancelled"},
				},
			},
			expected: []string{},
		},
		{
			input: Input{
				Orders: []Order{
					{ID: "a", UpdatedAt: 2, Status: "open"},
					{ID: "a", UpdatedAt: 1, Status: "open"},
				},
			},
			expected: []string{"a"},
		},
	}

	for _, tc := range tests {
		// We need to convert tc.input to map[string]any to match solve's signature
		// because solve takes map[string]any which is what main.go does.
		b, _ := json.Marshal(tc.input)
		var inputMap map[string]any
		_ = json.Unmarshal(b, &inputMap)

		res := solve(inputMap)

		// Convert res to []string for comparison
		// solve returns any, which is likely []string based on implementation
		var actual []string
		bRes, _ := json.Marshal(res)
		_ = json.Unmarshal(bRes, &actual)

		if !reflect.DeepEqual(actual, tc.expected) {
			t.Errorf("input %v: got %v, want %v", tc.input, actual, tc.expected)
		}
	}
}

