package main

import "sort"

func solve(x map[string]any) any {
	latest := make(map[string]map[string]any)
	orders, ok := x["orders"].([]any)
	if !ok {
		return []string{}
	}

	for _, raw := range orders {
		o := raw.(map[string]any)
		k := o["id"].(string)
		u := o["updatedAt"].(float64)

		if old, ok := latest[k]; ok {
			oldU := old["updatedAt"].(float64)
			if u >= oldU {
				latest[k] = o
			}
		} else {
			latest[k] = o
		}
	}

	out := []string{}
	for k, v := range latest {
		if v["status"].(string) != "cancelled" {
			out = append(out, k)
		}
	}
	sort.Strings(out)
	return out
}

