package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestSolveRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "empty layers",
			input:    `{"layers": []}`,
			expected: `{}`,
		},
		{
			name:     "single layer",
			input:    `{"layers": [{"a": 1}]}`,
			expected: `{"a": 1}`,
		},
		{
			name:     "two layers merge",
			input:    `{"layers": [{"a": 1}, {"b": 2}]}`,
			expected: `{"a": 1, "b": 2}`,
		},
		{
			name:     "null deletes key",
			input:    `{"layers": [{"a": 1, "b": 2}, {"a": nil}]}`,
			expected: `{"b": 2}`,
		},
		{
			name:     "array replacement",
			input:    `{"layers": [{"a": [1, 2]}, {"a": [3]}]}`,
			expected: `{"a": [3]}`,
		},
		{
			name:     "recursive object merge",
			input:    `{"layers": [{"a": {"b": 1, "c": 2}}, {"a": {"b": 3}}]}`,
			expected: `{"a": {"b": 3, "c": 2}}`,
