package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		input    map[string]any
		expected []any
	}{
		{
			input: map[string]any{
				"windows": [][]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: [][]float64{{1, 8}, {9, 10}},
		},
		{
			input: map[string]any{
				"windows": [][]float64{{1, 1}, {2, 2}, {3, 2}}, // empty and reversed
			},
			expected: [][]float64{},
		},
		{
			input: map[string]any{
				"windows": [][]float64{{-10, -5}, {-7, -2}, {-3, 0}}, // negative endpoints and merging
			},
			expected: [][]float64{{-10, -2}, {-3, 0}}, // wait, -10, -5 and -7, -2 overlap/touch. [-10, -2]. Then [-3, 0] doesn't overlap [-10, -2].
		},
	}

	// Re-evaluating the negative case:
	// [-10, -5], [-7, -2], [-3, 0]
	// 1. [-10, -5]
	// 2. [-7, -2] overlaps [-10, -5] because -7 <= -5. New interval: [-10, max(-5, -2)] = [-10, -2]
	// 3. [-3, 0] does not overlap [-10, -2] because -3 > -2.
	// So expected is [[-10, -2], [-3, 0]]

	for i, tt := range tests {
		res := solve(tt.input)
		// The solve function returns any, which is often a [][]float64 or similar.
		// To compare easily, we marshal and unmarshal to avoid type issues with float64 vs int etc.
		// But solve returns [][2]float64 according to its implementation.

		// Let's use a more reliable comparison by converting result to JSON and then to expected type.
		b, _ := json.Marshal(res)
		var actual any
		_ = json.Unmarshal(b, &actual)

		// We need to marshal expected to compare JSONs or just compare slices.
		// Since expected is [][]float64, let's use that.
		// But tt.expected is []any in my struct. Let's fix it.
	}
}

package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    map[string]any
		expected []any
	}{
		{
			name: "README example",
			input: map[string]any{
				"windows": [][]float64{{5, 8}, {1, 3}, {3, 5}, {9, 10}},
			},
			expected: [][]float64{{1, 8}, {9, 10}},
		},
		{
			name: "Empty and reversed windows",
			input: map[string]any{
				"windows": [][]float64{{1, 1}, {2, 2}, {3, 2}},
			},
			expected: [][]float64{},
		},
		{
			name: "Negative endpoints",
			input: map[string]any{
				"windows": [][]float64{{-10, -5}, {-7, -2}, {-3, 0}},
			},
			expected: [][]float64{{-10, -2}, {-3, 0}},
		},
		{
			name: "Touching windows",
			input: map[string]any{
				"windows": [][]float64{{1, 2}, {2, 3}},
			},
			expected: [][]float64{{1, 3}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			res := solve(tt.input)
			// To compare correctly, we'll convert everything to JSON and back to avoid type differences
			// because float64 in JSON might be treated differently than what's in the slice.
			// But here we are creating everything in Go.

			bRes, _ := json.Marshal(res)
			var actual any
			_ = json.Unmarshal(bRes, &actual)

			bExp, _ := json.Marshal(tt.expected)
			var expected any
			_ = json.Unmarshal(bExp, &expected)

			if !reflect.DeepEqual(actual, expected) {
				t.Errorf("got %v, want %v", actual, expected)
			}
		})
	}
}

