package main

import "sort"

func solve(x map[string]any) any {
	windows, ok := x["windows"].([]any)
	if !ok {
		return [][2]float64{}
	}

	rows := [][2]float64{}
	for _, raw := range windows {
		v, ok := raw.([]any)
		if !ok || len(v) < 2 {
			continue
		}
		a, ok1 := v[0].(float64)
		b, ok2 := v[1].(float64)
		if ok1 && ok2 && a < b {
			rows = append(rows, [2]float64{a, b})
		}
	}

	sort.Slice(rows, func(i, j int) bool {
		if rows[i][0] != rows[j][0] {
			return rows[i][0] < rows[j][0]
		}
		return rows[i][1] < rows[j][1]
	})

	out := [][2]float64{}
	for _, v := range rows {
		n := len(out)
		if n > 0 && v[0] <= out[n-1][1] {
			if v[1] > out[n-1][1] {
				out[n-1][1] = v[1]
			}
		} else {
			out = append(out, v)
		}
	}
	return out
}

