import unittest
from logic import solve

class TestMaintenanceWindows(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(solve({'windows': []}), [])

    def test_single_window(self):
        self.assertEqual(solve({'windows': [[1, 5]]}), [[1, 5]])

    def test_discard_empty_and_reversed(self):
        # Empty [5,5] and reversed [5,3] should be discarded. [2,4] remains.
        self.assertEqual(solve({'windows': [[5, 5], [5, 3], [2, 4]]}), [[2, 4]])

    def test_touching_windows(self):
        self.assertEqual(solve({'windows': [[1, 2], [2, 3]]}), [[1, 3]])

    def test_overlapping_windows(self):
        self.assertEqual(solve({'windows': [[1, 3], [2, 4]]}), [[1, 4]])

    def test_nested_windows(self):
        self.assertEqual(solve({'windows': [[1, 10], [2, 5]]}), [[1, 10]])

    def test_negative_windows(self):
        self.assertEqual(solve({'windows': [[-10, -5], [-7, -2]]}), [[-10, -2]])

    def test_multiple_touching_and_disjoint(self):
        self.assertEqual(solve({'windows': [[1, 2], [2, 3], [5, 6], [6, 7]]}), [[1, 3], [5, 7]])

    def test_disjoint_windows(self):
        self.assertEqual(solve({'windows': [[1, 2], [3, 4]]}), [[1, 2], [3, 4]])

    def test_readme_example(self):
        self.assertEqual(solve({'windows': [[5, 8], [1, 3], [3, 5], [9, 10]]}), [[1, 8], [9, 10]])

if __name__ == '__main__':
    unittest.main()

