from database import connect
class Ledger:
 def __init__(self,path): self.db=connect(path)
 def record(self,events):
  with self.db:
   for e in events:
    self.db.execute("INSERT OR IGNORE INTO events (id, account, amount, status) VALUES (?, ?, ?, ?)",
                    (e['id'], e['account'], e['amount'], e['status']))
 def totals(self):
  rows = self.db.execute("SELECT account, SUM(amount) FROM events WHERE status = 'posted' GROUP BY account").fetchall()
  return {row[0]: row[1] for row in rows}
 def close(self): self.db.close()

