def apply(path,events):
 # Feature: validate the COMPLETE batch before opening a write transaction.
 # id/account: nonempty strings; amount: integer, not bool; status: posted/pending.
 # Raise ValueError for invalid records. Then persist and return current totals.
 for e in events:
  if not isinstance(e, dict): raise ValueError("not a dict")
  eid=e.get('id')
  if not isinstance(eid, str) or not eid: raise ValueError("invalid id")
  acc=e.get('account')
  if not isinstance(acc, str) or not acc: raise ValueError("invalid account")
  amt=e.get('amount')
  if not isinstance(amt, int) or isinstance(amt, bool): raise ValueError("invalid amount")
  stat=e.get('status')
  if stat not in ('posted', 'pending'): raise ValueError("invalid status")
 ledger=Ledger(path)
 try:
  ledger.record(events)
  return ledger.totals()
  finally:
   ledger.close()

