import unittest
import json
import subprocess
import sys
from logic import solve

class TestMaintenanceWindows(unittest.TestCase):
    def test_readme_example(self):
        input_data = {"windows": [[5, 8], [1, 3], [3, 5], [9, 10]]}
        expected = [[1, 8], [9, 10]]
        self.assertEqual(solve(input_data), expected)

    def test_empty_and_reversed_windows(self):
        input_data = {"windows": [[1, 1], [5, 5], [10, 5], [5, 10]]}
        # [1,1] is empty, [5,5] is empty, [10,5] is reversed. [5,10] is valid.
        expected = [[5, 10]]
        self.assertEqual(solve(input_data), expected)

    def test_touching_windows(self):
        input_data = {"windows": [[1, 2], [2, 3], [3, 4]]}
        expected = [[1, 4]]
        self.assertEqual(solve(input_data), expected)

    def test_overlapping_windows(self):
        input_data = {"windows": [[1, 5], [2, 4], [3, 6]]}
        expected = [[1, 6]]
        self.assertEqual(solve(input_data), expected)

    def test_negative_windows(self):
        input_data = {"windows": [[-10, -5], [-7, -3], [-2, 0]]}
        # [-10, -5] and [-7, -3] overlap -> [-10, -3]
        # [-2, 0] is separate.
        expected = [[-10, -3], [-2, 0]]
        self.assertEqual(solve(input_data), expected)

    def test_empty_input(self):
        input_data = {"windows": []}
        expected = []
        self.assertEqual(solve(input_data), expected)

    def test_single_window(self):
        input_data = {"windows": [[1, 10]]}
        expected = [[1, 10]]
        self.assertEqual(solve(input_data), expected)

    def test_un-sorted_input(self):
        input_data = {"windows": [[9, 10], [1, 3], [3, 5], [5, 8]]}
        expected = [[1, 8], [9, 10]]
        self.assertEqual(solve(input_data), expected)

if __name__ == "__main__":
    unittest.main()

