package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	testCases := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "README example",
			input:    `[{"windows": [[5, 8], [1, 3], [3, 5], [9, 10]]}]`,
			expected: `[[[1, 8], [9, 10]]]`,
		},
		{
			name:     "Empty or reversed windows",
			input:    `[{"windows": [[5, 5], [6, 4]]}]`,
			expected: `[[]]`,
		},
		{
			name:     "Negative windows",
			input:    `[{"windows": [[-10, -5], [-7, -2]]}]`,
			expected: `[[[-10, -2]]]`,
		},
		{
			name:     "Overlapping windows",
			input:    `[{"windows": [[1, 5], [2, 6]]}]`,
			expected: `[[[1, 6]]]`,
		},
		{
			name:     "Touching windows",
			input:    `[{"windows": [[1, 5], [5, 6]]}]`,
			expected: `[[[1, 6]]]`,
		},
		{
			name:     "Disjoint windows",
			input:    `[{"windows": [[1, 2], [3, 4]]}]`,
			expected: `[[[1, 2], [3, 4]]]`,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			var inputs []map[string]any
			if err := json.Unmarshal([]byte(tc.input), &inputs); err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			var out []any
			for _, x := range inputs {
				out = append(out, solve(x))
			}

			actualBytes, err := json.Marshal(out)
			if err != nil {
				t.Fatalf("failed to marshal out: %v", err)
			}

			var expectedAny any
			if err := json.Unmarshal([]byte(tc.expected), &expectedAny); err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			// To compare properly, unmarshal both as generic maps/slices
			var actualAny any
			if err := json.Unmarshal(actualBytes, &actualAny); err != nil {
				t.Fatalf("failed to unmarshal actual: %v", err)
			}

			if !reflect.DeepEqual(actualAny, expectedAny) {
				t.Errorf("got %v want %v", actualAny, expectedAny)
			}
		})
	}
}

