import json,subprocess,sys
import unittest

class TestSolve(unittest.TestCase):
    def run_solve(self, cases):
        p = subprocess.run([sys.executable, "main.py", json.dumps(cases)], capture_output=True, text=True, check=True)
        return json.loads(p.stdout)

    def test_public_cases(self):
        cases = [{'orders': []}, {'orders': [{'id': 'a', 'updatedAt': 1, 'status': 'open'}]}]
        expected = [[], ['a']]
        self.assertEqual(self.run_solve(cases), expected)

    def test_readme_example(self):
        cases = [{
            "orders": [
                {"id": "b", "updatedAt": 3, "status": "cancelled"},
                {"id": "b", "updatedAt": 1, "status": "open"},
                {"id": "a", "updatedAt": 2, "status": "open"}
            ]
        }]
        expected = [["a"]]
        self.assertEqual(self.run_solve(cases), expected)

    def test_tie_breaking(self):
        # Tie in updatedAt, later record wins
        cases = [{
            "orders": [
                {"id": "b", "updatedAt": 1, "status": "open"},
                {"id": "b", "updatedAt": 1, "status": "cancelled"}
            ]
        }]
        expected = [[]]
        self.assertEqual(self.run_solve(cases), expected)

    def test_order_update_logic(self):
        # Update with higher updatedAt
        cases = [{
            "orders": [
                {"id": "b", "updatedAt": 1, "status": "open"},
                {"id": "b", "updatedAt": 3, "status": "cancelled"}
            ]
        }]
        expected = [[]]
        self.assertEqual(self.run_solve(cases), expected)

        # Update with higher updatedAt but different status
        cases = [{
            "orders": [
                {"id": "b", "updatedAt": 3, "status": "cancelled"},
                {"id": "b", "updatedAt": 1, "status": "open"}
            ]
        }]
        expected = [["a"]] # wait, no, this should be ["a"] if 'a' is there.
        # Let's redo the test case for clarity
        cases = [{
            "orders": [
                {"id": "b", "updatedAt": 3, "status": "cancelled"},
                {"id": "b", "updatedAt": 1, "status": "open"},
                {"id": "a", "updatedAt": 2, "status": "open"}
            ]
        }]
        expected = [["a"]]
        self.assertEqual(self.run_solve(cases), expected)

    def test_sorting(self):
        # Result should be sorted lexicographically
        cases = [{
            "orders": [
                {"id": "z", "updatedAt": 1, "status": "open"},
                {"id": "a", "updatedAt": 1, "status": "open"},
                {"id": "m", "updatedAt": 1, "status": "open"}
            ]
        }]
        expected = [["a", "m", "z"]]
        self.assertEqual(self.run_solve(cases), expected)

if __name__ == "__main__":
    unittest.main()

