package main

func solve(x map[string]any) any {
	events := x["events"].([]any)
	now := x["now"].(float64)
	window := x["window"].(float64)
	lowerBound := now - window

	out := make(map[string]float64)
	for _, raw := range events {
		e := raw.(map[string]any)
		at := e["at"].(float64)
		if at >= lowerBound && at <= now {
			user := e["user"].(string)
			units := e["units"].(float64)
			out[user] += units
		}
	}
	return out
}

package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestRegression(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expected string
	}{
		{
			name:     "empty events",
			input:    `[{"events": [], "now": 100, "window": 10}]`,
			expected: `[{}]`,
		},
		{
			name:     "events at bounds",
			input:    `[{"events": [{"user": "a", "at": 90, "units": 1}, {"user": "b", "at": 100, "units": 2}, {"user": "c", "at": 95, "units": 3}], "now": 100, "window": 10}]`,
			expected: `[{"a":1,"b":2,"c":3}]`,
		},
		{
			name:     "events outside bounds",
			input:    `[{"events": [{"user": "a", "at": 89, "units": 1}, {"user": "b", "at": 101, "units": 2}, {"user": "c", "at": 95, "units": 3}], "now": 100, "window": 10}]`,
			expected: `[{"c":3}]`,
		},
		{
			name:     "zero unit users and events",
			input:    `[{"events": [{"user": "a", "at": 95, "units": 0}, {"user": "b", "at": 95, "units": 5}], "now": 100, "window": 10}]`,
			expected: `[{"a":0,"b":5}]`,
		},
		{
			name:     "multiple users and events",
			input:    `[{"events": [{"user": "a", "at": 90, "units": 1}, {"user": "a", "at": 100, "units": 2}, {"user": "b", "at": 95, "units": 3}, {"user": "b", "at": 105, "units": 4}], "now": 100, "window": 10}]`,
			expected: `[{"a":3,"b":3}]`,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var inputs []map[string]any
			if err := json.Unmarshal([]byte(tt.input), &inputs); err != nil {
				t.Fatalf("failed to unmarshal input: %v", err)
			}

			var expected []any
			if err := json.Unmarshal([]byte(tt.expected), &expected); err != nil {
				t.Fatalf("failed to unmarshal expected: %v", err)
			}

			for i, x := range inputs {
				res := solve(x)
				// Marshal res to JSON then unmarshal to any to match the comparison method used in TestPublic
				b, _ := json.Marshal(res)
				var actual any
				_ = json.Unmarshal(b, &actual)

				if !reflect.DeepEqual(actual, expected[i]) {
					t.Errorf("case %d: got %v want %v", i, actual, expected[i])
				}
			}
		})
	}
}

