function runTest(input, expected) {
    const result = JSON.parse(execFileSync(process.execPath, ["main.cjs", JSON.stringify(input)], {encoding: "utf8"}));
    assert.deepEqual(result, expected);
}

// README example
runTest({windows: [[5, 8], [1, 3], [3, 5], [9, 10]]}, [[1, 8], [9, 10]]);

// Empty windows
runTest({windows: []}, []);

// Single window
runTest({windows: [[1, 2]]}, [[1, 2]]);

// Reversed and empty windows (should be discarded)
runTest({windows: [[5, 1], [3, 3], [2, 4]]}, [[2, 4]]);

// Touching windows
runTest({windows: [[1, 2], [2, 3]]}, [[1, 3]]);

// Overlapping windows
runTest({windows: [[1, 3], [2, 4]]}, [[1, 4]]);

// Negative endpoints
runTest({windows: [[-5, -2], [-2, 0], [1, 3]]}, [[-5, 0], [1, 3]]);

// Negative and zero
runTest({windows: [[-2, -1], [-1, 0], [0, 1]]}, [[-2, 1]]);

console.log("All regression tests passed");

