exports.solve = function(x) {
  const out = [];
  const rows = x.windows
    .filter(([a, b]) => a < b)
    .map(r => [...r])
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  for (const [start, end] of rows) {
    if (out.length > 0 && start <= out[out.length - 1][1]) {
      out[out.length - 1][1] = Math.max(out[out.length - 1][1], end);
    } else {
      out.push([start, end]);
    }
  }
  return out;
};

