import unittest
from logic import solve

class TestLogic(unittest.TestCase):
    def test_empty_events(self):
        self.assertEqual(solve({'events': [], 'now': 100, 'window': 10}), {})

    def test_event_at_start_of_window(self):
        # [90, 100]
        self.assertEqual(solve({'events': [{'user': 'a', 'at': 90, 'units': 5}], 'now': 100, 'window': 10}), {'a': 5})

    def test_event_at_end_of_window(self):
        # [90, 100]
        self.assertEqual(solve({'events': [{'user': 'a', 'at': 100, 'units': 5}], 'now': 100, 'window': 10}), {'a': 5})

    def test_event_just_outside_start_of_window(self):
        # [90, 100]
        self.assertEqual(solve({'events': [{'user': 'a', 'at': 89, 'units': 5}], 'now': 100, 'window': 10}), {})

    def test_event_just_outside_end_of_window(self):
        # [90, 100]
        self.assertEqual(solve({'events': [{'user': 'a', 'at': 101, 'units': 5}], 'now': 100, 'window': 10}), {})

    def test_zero_unit_event_in_window(self):
        # [90, 100]
        self.assertEqual(solve({'events': [{'user': 'a', 'at': 95, 'units': 0}], 'now': 100, 'window': 10}), {'a': 0})

    def test_multiple_events_in_window(self):
        # [90, 100]
        events = [
            {'user': 'a', 'at': 90, 'units': 3},
            {'user': 'a', 'at': 95, 'units': 2},
            {'user': 'a', 'at': 100, 'units': 1}
        ]
        self.assertEqual(solve({'events': events, 'now': 100, 'window': 10}), {'a': 6})

    def test_mixed_events_in_and_out_of_window(self):
        # [90, 100]
        events = [
            {'user': 'a', 'at': 90, 'units': 3},
            {'user': 'a', 'at': 100, 'units': 2},
            {'user': 'b', 'at': 101, 'units': 9},
            {'user': 'c', 'at': 89, 'units': 4}
        ]
        self.assertEqual(solve({'events': events, 'now': 100, 'window': 10}), {'a': 5})

if __name__ == '__main__':
    unittest.main()
